const vec2 uLensS = vec2(1.0, 1.0);
const vec2 uLensF = vec2(0.5, 1.0);
const float scale = 1.;

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;

    float Fx = uLensF.x;
    float Fy = uLensF.y;

    vec2 newUv = uv * 2.0 - 1.0;
    newUv.x = newUv.x + ((pow(newUv.y, 2.0) / scale) * newUv.x / scale) * -Fx;
    newUv.y = newUv.y + ((pow(newUv.x, 2.0) / scale) * newUv.y / scale) * -Fy;
    newUv = newUv * uLensS;

    newUv = newUv / scale * 0.5 + 0.5;

    fragColor = texture(iChannel0, newUv);
}
